"""Build the PDF fixtures `tests/test_ws32_pdf_resume.py` reads (WS-32).

Run it from the repository root::

    ./env/Scripts/python.exe tests/fixtures/pdf/make_fixtures.py

The five ``.pdf`` files beside this script are **generated by this script** and
committed, so the binaries are not unexplained blobs. They are written by hand
at the byte level (stdlib ``zlib`` for the streams, the xref table assembled
here) rather than by a PDF *authoring* library: the fixtures exist to prove
what a reader **reads**, and a fixture produced by a writer proves the writer,
not the reader. The one exception is the encrypted variant, which is
`resume_with_text.pdf` re-saved with a user password — encrypting is a writer's
job, pypdf already ships one, and re-inventing it here would be noise rather
than evidence.

Each fixture is one shape of "a PDF a candidate might upload":

``resume_with_text.pdf``
    A real text layer in a standard-14 Helvetica (``/Type1`` +
    ``WinAnsiEncoding``, so no font embedding is needed). It parses into a
    populated profile — name, email and an ``EXPERIENCE`` section — because
    its section headings are spelled as the exact ``_SECTION_HEADINGS`` keys
    of ``src/resume/parser.py``, each on its own line.
``resume_scanned.pdf``
    One page whose content stream draws a FlateDecode raw-RGB image XObject
    and contains **no text operators at all** — a scan in a PDF wrapper.
    Extraction must yield no text.
``resume_mojibake.pdf``
    A Type0/CID font with ``/Encoding /Identity-H`` and a ``/ToUnicode`` CMap
    that deliberately maps every code to U+FFFD — the *mapped-to-FFFD* shape.
    Extraction yields runs of ``\\ufffd``, which is what makes the parser's
    "not readable text" refusal testable for a text layer that says, in so many
    words, that its glyphs are not Unicode.
``resume_no_tounicode.pdf``
    The **unmapped** shape of the same breakage, and the one that appears in
    the wild when a font is mis-embedded: the identical Type0/CID font with the
    ``/ToUnicode`` entry omitted entirely. pypdf cannot map the two-byte codes
    at all, so it passes them through and extraction yields the raw control
    characters (U+0001…U+001F) with not a single U+FFFD. A reader that watched
    only for the replacement character would build a profile whose "name" is a
    run of control characters; this fixture is what pins that refusal.
``resume_encrypted.pdf``
    ``resume_with_text.pdf`` re-written with a user password. Its purpose is
    only that ``PdfReader(...).is_encrypted`` is True.

The script prints, for each fixture, what ``PdfReader(...).pages[0]``
``.extract_text()`` returns (or the pypdf refusal), so a maintainer can see
that a fixture does what its name claims without opening a PDF viewer.

Re-running the script reproduces the unencrypted fixtures **byte for byte**
(the object bytes, the compressed streams and the xref offsets are all
deterministic). The encrypted one will differ on every run: pypdf derives a
fresh encryption key and salt per write, which is the point of encryption. A
regenerated ``resume_encrypted.pdf`` is therefore an expected diff, not a
broken fixture.
"""

from __future__ import annotations

import unicodedata
import zlib
from pathlib import Path

HERE = Path(__file__).parent

PAGE_WIDTH, PAGE_HEIGHT = 612, 792
LEFT_MARGIN, FIRST_BASELINE = 72, 748


# --- the hand-rolled PDF writer ---------------------------------------------


def _stream(entries: str, payload: bytes) -> bytes:
    """A stream object: dictionary entries plus a FlateDecode-compressed payload."""
    compressed = zlib.compress(payload, 9)
    head = f"<< {entries} /Length {len(compressed)} /Filter /FlateDecode >>".encode("ascii")
    return head + b"\nstream\n" + compressed + b"\nendstream"


def _content_stream(payload: bytes) -> bytes:
    """A page's content stream (a plain stream, the way a producer writes one)."""
    return _stream("", payload)


def _cmap_stream(payload: bytes) -> bytes:
    """The ``/ToUnicode`` CMap stream of a font."""
    return _stream("/Type /CMap", payload)


def _write_pdf(path: Path, objects: list[bytes]) -> None:
    """Serialize objects 1..n with a correct cross-reference table.

    The xref offsets are the byte offsets of each ``n 0 obj`` in the finished
    file, so the file is assembled in memory and the offsets are measured as
    the bytes are appended.
    """
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets: list[int] = []
    for number, body in enumerate(objects, start=1):
        offsets.append(len(out))
        out += f"{number} 0 obj\n".encode("ascii") + body + b"\nendobj\n"

    xref_offset = len(out)
    out += f"xref\n0 {len(objects) + 1}\n".encode("ascii")
    out += b"0000000000 65535 f \n"
    for offset in offsets:
        out += f"{offset:010d} 00000 n \n".encode("ascii")
    out += (
        f"trailer\n<< /Size {len(objects) + 1} /Root 1 0 R >>\n"
        f"startxref\n{xref_offset}\n%%EOF\n"
    ).encode("ascii")
    path.write_bytes(bytes(out))


def _escape(text: str) -> bytes:
    """A PDF literal string body (WinAnsi; the fixture text is ASCII)."""
    return (
        text.replace("\\", "\\\\")
        .replace("(", "\\(")
        .replace(")", "\\)")
        .encode("cp1252", errors="replace")
    )


def _page_object(content_object: int, resources: str) -> bytes:
    return (
        f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {PAGE_WIDTH} {PAGE_HEIGHT}] "
        f"/Resources << {resources} >> /Contents {content_object} 0 R >>"
    ).encode("ascii")


def _catalog_and_page_tree() -> list[bytes]:
    """Objects 1 and 2: the catalog and a one-page page tree."""
    return [
        b"<< /Type /Catalog /Pages 2 0 R >>",
        b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    ]


# --- the five fixtures ------------------------------------------------------

# The résumé text. Every heading is an exact ``_SECTION_HEADINGS`` key of
# ``src/resume/parser.py`` on a line of its own, because a heading the parser
# does not recognize is a section it does not read; the experience entries use
# the ``title | company | dates`` shape `_parse_experience` splits on.
RESUME_LINES: list[tuple[str, int]] = [
    ("Ada Lovelace", 20),
    ("Analytical Engine Programmer", 12),
    ("ada@example.com | +44 20 7946 0958 | London, UK", 10),
    ("", 10),
    ("PROFESSIONAL SUMMARY", 13),
    ("Mathematician and writer, author of the first published algorithm.", 10),
    ("", 10),
    ("EXPERIENCE", 13),
    ("Senior Programmer | Analytical Engines Ltd | 1843-1852", 11),
    ("- Wrote the first algorithm intended for a machine.", 10),
    ("- Documented the Analytical Engine's programmed behaviour.", 10),
    ("Research Fellow | Institute of Mathematics | 1835-1843", 11),
    ("- Translated and annotated Menabrea's notes on the engine.", 10),
    ("", 10),
    ("EDUCATION", 13),
    ("Bachelor of Science | University of London | 1832-1835", 11),
    ("GPA: 3.9/4.0", 10),
    ("", 10),
    ("SKILLS", 13),
    ("Languages: Mathematics, Notation, Analytical Engines", 10),
]


def _resume_text_stream(lines: list[tuple[str, int]]) -> bytes:
    """The résumé text as a content stream.

    Each line gets its own absolute text matrix (``Tm``) rather than a
    relative ``Td`` step: absolute placement is what typesetting software
    emits, and it keeps the extractor's line grouping predictable.
    """
    parts = [b"BT"]
    y = FIRST_BASELINE
    previous_size: int | None = None
    for text, size in lines:
        if not text:
            y -= 16
            continue
        parts.append(f"1 0 0 1 {LEFT_MARGIN} {y} Tm".encode("ascii"))
        if size != previous_size:
            parts.append(f"/F1 {size} Tf".encode("ascii"))
            previous_size = size
        parts.append(b"(" + _escape(text) + b") Tj")
        y -= max(size + 8, 16)
    parts.append(b"ET")
    return b"\n".join(parts)


def build_text_fixture(path: Path) -> None:
    """`resume_with_text.pdf`: a Helvetica text layer holding a whole résumé."""
    objects = [
        *_catalog_and_page_tree(),
        _page_object(content_object=4, resources="/Font << /F1 5 0 R >>"),
        _content_stream(_resume_text_stream(RESUME_LINES)),
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
    ]
    _write_pdf(path, objects)


def _grey_image_stream() -> bytes:
    """One 8x8 raw-RGB image, FlateDecode-compressed.

    The raw samples are written as literal bytes rather than as a filter with
    parameters: the point of the fixture is that the page carries an image and
    no text, and a plain ``/Filter /FlateDecode`` is the least machinery that
    gets there.
    """
    samples = bytearray()
    for row in range(8):
        for column in range(8):
            value = 255 if (row + column) % 2 == 0 else 128
            samples += bytes((value, value, value))
    return zlib.compress(bytes(samples), 9)


def build_scanned_fixture(path: Path) -> None:
    """`resume_scanned.pdf`: an image page with no text operators.

    A scan of a résumé is a photograph in a PDF wrapper: the page paints an
    image and its content stream mentions no font and no ``Tj``/``TJ``. The
    image is a 64x64 checkerboard — enough to be a real XObject.
    """
    image = _grey_image_stream()
    image_object = (
        f"<< /Type /XObject /Subtype /Image /Width 8 /Height 8 /ColorSpace /DeviceRGB "
        f"/BitsPerComponent 8 /Filter /FlateDecode /Length {len(image)} >>\nstream\n"
    ).encode("ascii") + image + b"\nendstream"
    content = b"q 468 0 0 648 72 72 cm /Im0 Do Q\n"

    objects = [
        *_catalog_and_page_tree(),
        _page_object(content_object=4, resources="/XObject << /Im0 5 0 R >>"),
        _content_stream(content),
        image_object,
    ]
    _write_pdf(path, objects)


def _to_unicode_cmap() -> bytes:
    """A CMap that maps codes 1..0x20 to U+FFFD, deliberately.

    This is `resume_mojibake.pdf`'s whole point: a CID font whose ToUnicode
    table says its glyphs do **not** correspond to Unicode. pypdf honours the
    table, so extraction yields replacement characters.
    """
    entries = "".join(f"<{code:04x}> <fffd>\n" for code in range(1, 0x21))
    return (
        b"/CIDInit /ProcSet findresource begin\n"
        b"12 dict begin\nbegincmap\n"
        b"/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def\n"
        b"/CMapName /Adobe-Identity-UCS def\n/CMapType 2 def\n"
        b"1 begincodespacerange\n<0000> <ffff>\nendcodespacerange\n"
        b"32 beginbfchar\n" + entries.encode("ascii") + b"endbfchar\n"
        b"endcmap\nCMapName currentdict /CMap defineresource pop\nend\nend\n"
    )


#: The two-byte codes the broken-CID fixtures show: <0001>…<0020>. Identity-H
#: text is shown as hexadecimal codes, so a CID font with no usable Unicode
#: mapping hands the reader raw control-character codes.
_CID_SHOWN_TEXT = (
    b"<" + b"".join(f"{code:04x}".encode("ascii") for code in range(1, 0x21)) + b"> Tj"
)

_CID_DESCRIPTOR = (
    b"<< /Type /FontDescriptor /FontName /BrokenCID /Flags 4 "
    b"/FontBBox [0 -200 1000 900] /ItalicAngle 0 /Ascent 900 /Descent -200 "
    b"/CapHeight 700 /StemV 80 >>"
)


def _cid_content_stream() -> bytes:
    return _content_stream(b"BT\n1 0 0 1 72 748 Tm\n/F1 12 Tf\n" + _CID_SHOWN_TEXT + b"\nET\n")


def build_mojibake_fixture(path: Path) -> None:
    """`resume_mojibake.pdf`: a Type0 CID font that extracts as U+FFFD runs.

    The text is shown as two-byte codes (``Identity-H``) that the ToUnicode
    CMap **maps to U+FFFD**. This is the mapped-to-FFFD shape: the document
    carries a table, and the table says the glyphs are not Unicode. What a
    program reads out of it is the replacement character — and that is the fact
    the parser has to refuse. `resume_no_tounicode.pdf` is the other shape.
    """
    objects = [
        *_catalog_and_page_tree(),
        _page_object(content_object=4, resources="/Font << /F1 5 0 R >>"),
        _cid_content_stream(),
        (
            b"<< /Type /Font /Subtype /Type0 /BaseFont /BrokenCID /Encoding /Identity-H "
            b"/DescendantFonts [6 0 R] /ToUnicode 7 0 R >>"
        ),
        (
            b"<< /Type /Font /Subtype /CIDFontType2 /BaseFont /BrokenCID "
            b"/CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> "
            b"/FontDescriptor 8 0 R /DW 1000 >>"
        ),
        _cmap_stream(_to_unicode_cmap()),
        _CID_DESCRIPTOR,
    ]
    _write_pdf(path, objects)


def build_no_tounicode_fixture(path: Path) -> None:
    """`resume_no_tounicode.pdf`: the *unmapped* shape of a broken CID font.

    The same Type0/Identity-H/CIDFontType2 font as `resume_mojibake.pdf`, with
    the ``/ToUnicode`` entry **omitted entirely** — which is what a font that
    was never embedded, or was embedded without its Unicode table, looks like.
    There is no mapping to honour, so pypdf passes the two-byte codes straight
    through: extraction yields control characters (U+0001…U+001F) and **no**
    U+FFFD at all.
    """
    objects = [
        *_catalog_and_page_tree(),
        _page_object(content_object=4, resources="/Font << /F1 5 0 R >>"),
        _cid_content_stream(),
        # No /ToUnicode here, and no CMap object in the file.
        (
            b"<< /Type /Font /Subtype /Type0 /BaseFont /BrokenCID /Encoding /Identity-H "
            b"/DescendantFonts [6 0 R] >>"
        ),
        (
            b"<< /Type /Font /Subtype /CIDFontType2 /BaseFont /BrokenCID "
            b"/CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> "
            b"/FontDescriptor 7 0 R /DW 1000 >>"
        ),
        _CID_DESCRIPTOR,
    ]
    _write_pdf(path, objects)


def build_encrypted_fixture(path: Path) -> None:
    """`resume_encrypted.pdf`: the text fixture re-written with a user password."""
    import pypdf

    reader = pypdf.PdfReader(str(HERE / "resume_with_text.pdf"))
    writer = pypdf.PdfWriter()
    for page in reader.pages:
        writer.add_page(page)
    writer.encrypt(user_password="ws32-fixture", owner_password="ws32-fixture")
    with path.open("wb") as handle:
        writer.write(handle)


# --- verification -----------------------------------------------------------


def _report(path: Path) -> None:
    """Print what pypdf makes of the fixture, so the binaries are inspectable."""
    import pypdf

    try:
        reader = pypdf.PdfReader(str(path))
        if reader.is_encrypted:
            print(f"{path.name}\n    is_encrypted: True (extraction not attempted)")
            return
        text = reader.pages[0].extract_text()
    except Exception as exc:  # noqa: BLE001 — pypdf's refusal is a result here
        print(f"{path.name}\n    pypdf raised {type(exc).__name__}: {exc}")
        return
    shown = text if len(text) <= 400 else text[:400] + "..."
    print(f"{path.name}\n    extract_text() -> {shown!r}")
    print(
        f"    characters: {len(text)}; replacement characters: {text.count(chr(0xFFFD))}; "
        f"control/format characters: {sum(1 for char in text if _is_unreadable_char(char))}"
    )


def _is_unreadable_char(char: str) -> bool:
    """A character no résumé's text layer would carry.

    This mirrors the rule ``src/resume/parser.py`` applies to a PDF's text
    layer — U+FFFD, a C0/C1 control character other than whitespace, or a
    Unicode ``Cf`` (format) character — so the summary printed below shows a
    maintainer exactly the count the refusal is built on. It is duplicated on
    purpose: a fixture generator importing the code under test would no longer
    be able to describe a fixture whose behaviour the code gets wrong.
    """
    codepoint = ord(char)
    if char == "\ufffd":
        return True
    if char in "\t\n\r" or char == " ":
        return False
    if codepoint <= 0x1F or 0x7F <= codepoint <= 0x9F:
        return True
    return unicodedata.category(char) == "Cf"


def main() -> None:
    build_text_fixture(HERE / "resume_with_text.pdf")
    build_scanned_fixture(HERE / "resume_scanned.pdf")
    build_mojibake_fixture(HERE / "resume_mojibake.pdf")
    build_no_tounicode_fixture(HERE / "resume_no_tounicode.pdf")
    build_encrypted_fixture(HERE / "resume_encrypted.pdf")

    print("wrote five fixtures; what pypdf extracts from each:\n")
    for name in (
        "resume_with_text.pdf",
        "resume_scanned.pdf",
        "resume_mojibake.pdf",
        "resume_no_tounicode.pdf",
        "resume_encrypted.pdf",
    ):
        _report(HERE / name)


if __name__ == "__main__":
    main()
